from .errors import AdmissionError

def check_ticket(ticket):
    if ticket.get("used_at") is not None:
        raise AdmissionError("TICKET_REUSED")
    if ticket.get("gate") not in {"north", "garden"}:
        raise AdmissionError("GATE_UNKNOWN")

